"use client";

import { useState, useEffect } from "react";
import { Clock, Trash2, Play, Search, X } from "lucide-react";
import Link from "next/link";
import { useWatch } from "@/context/WatchContext";

export default function HistoryPage() {
  const { history, clearHistory, removeFromHistory } = useWatch();
  const [search, setSearch] = useState("");
  const [filterType, setFilterType] = useState<"all" | "anime" | "movie" | "tv">("all");
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const handleClearAll = () => {
    if (confirm("Clear your entire watch history?")) {
      clearHistory();
    }
  };

  const filtered = history.filter((h) => {
    const matchesSearch = h.title.toLowerCase().includes(search.toLowerCase());
    const matchesType = filterType === "all" || h.type === filterType;
    return matchesSearch && matchesType;
  });

  const grouped: Record<string, typeof history> = {};
  filtered.forEach((entry) => {
    // History is sorted by updatedAt from context
    const date = new Date(entry.updatedAt).toLocaleDateString(undefined, {
      weekday: "long", year: "numeric", month: "long", day: "numeric",
    });
    if (!grouped[date]) grouped[date] = [];
    grouped[date].push(entry);
  });

  const relativeTime = (ts: number) => {
    const diff = (Date.now() - ts) / 1000;
    if (diff < 60) return "Just now";
    if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return `${Math.floor(diff / 86400)}d ago`;
  };

  const getHistoryLink = (entry: typeof history[0]) => {
    if (entry.type === 'movie') {
      return `/watch/movie/${entry.showId}`;
    }
    if (entry.type === 'tv') {
      const season = (entry as any).season || 1;
      const episode = entry.episodeId || entry.episodeNumber || 1;
      return `/watch/tv/${entry.showId}?s=${season}&e=${episode}`;
    }
    return `/watch/anime/${entry.showId}?ep=${entry.episodeId || 1}`;
  };

  const formatProgress = (current: number, total: number) => {
    if (!total || total <= 0) return '0%';
    return `${Math.min(100, Math.round((current / total) * 100))}%`;
  };

  if (!isMounted) return null;

  return (
    <main className="min-h-screen bg-[var(--bg-main)] text-[var(--text-main)] pt-16 md:pt-0 pb-24 md:pb-10 md:pl-[72px]">
      <div className="sticky top-0 z-40 bg-[var(--bg-overlay)] backdrop-blur-md border-b border-[var(--border-color)]">
        <div className="w-full px-6 md:px-12 px-4 md:px-6 py-4 flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <Clock className="w-6 h-6 text-purple-400" />
            <h1 className="text-xl md:text-2xl font-bold font-sora">Watch History</h1>
          </div>
          {history.length > 0 && (
            <button
              onClick={handleClearAll}
              className="flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-semibold text-red-400 hover:bg-red-500/10 transition-colors border border-red-500/30 hover:border-red-500/50"
            >
              <Trash2 className="w-4 h-4" />
              Clear All
            </button>
          )}
        </div>

        {history.length > 0 && (
          <div className="w-full px-6 md:px-12 px-4 md:px-6 pb-4">
            <div className="relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[var(--text-muted)]" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search history..."
                className="w-full bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg pl-10 pr-10 py-2.5 text-sm outline-none focus:border-purple-500 transition-colors"
              />
              {search && (
                <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2">
                  <X className="w-4 h-4 text-[var(--text-muted)]" />
                </button>
              )}
            </div>

            <div className="flex items-center gap-2 mt-4 overflow-x-auto hide-scrollbar pb-1">
              {(["all", "anime", "movie", "tv"] as const).map(type => (
                <button
                  key={type}
                  onClick={() => setFilterType(type)}
                  className={`px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-colors ${
                    filterType === type ? "bg-purple-600 text-white" : "bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-muted)] hover:text-white hover:border-white/20"
                  }`}
                >
                  {type === "all" ? "All History" : type === "anime" ? "Anime" : type === "movie" ? "Movies" : "TV Shows"}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="w-full px-6 md:px-12 px-4 md:px-6 py-8">
        {history.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-24 text-center opacity-50">
            <Clock className="w-16 h-16 mb-4 text-[var(--text-muted)]" />
            <p className="text-xl font-bold">No Watch History</p>
            <p className="text-sm text-[var(--text-muted)] mt-2">Content you watch will appear here</p>
            <Link href="/" className="mt-6 px-6 py-2 bg-purple-600 text-white rounded-full text-sm font-bold hover:bg-purple-700 transition-colors">
              Browse Movies & Anime
            </Link>
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16 opacity-50">
            <p className="font-semibold">No results for "{search}"</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.entries(grouped).map(([date, entries]) => (
              <div key={date}>
                <h2 className="text-sm font-bold text-[var(--text-muted)] uppercase tracking-wider mb-4 flex items-center gap-2">
                  <span className="w-8 h-px bg-[var(--border-color)]" />
                  {date}
                </h2>
                <div className="space-y-3">
                  {entries.map((entry, i) => (
                    <div key={entry.id} className="group flex items-center gap-4 p-3 rounded-xl bg-[var(--bg-card)] border border-[var(--border-color)] hover:border-white/10 transition-all">
                      <div className="relative w-24 md:w-32 aspect-video rounded-lg overflow-hidden shrink-0 bg-black/40">
                        {entry.poster && (
                          <img src={entry.poster} alt={entry.title} className="w-full h-full object-cover" />
                        )}
                        <div className="absolute inset-x-0 bottom-0 h-1 bg-white/20">
                          <div 
                            className="h-full bg-purple-500" 
                            style={{ width: formatProgress(entry.currentTime, entry.duration) }}
                          />
                        </div>
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <Play className="w-6 h-6 text-white fill-white shadow-lg" />
                        </div>
                      </div>

                      <div className="flex-1 min-w-0">
                        <Link href={getHistoryLink(entry)} className="hover:text-purple-400 transition-colors">
                          <h3 className="font-semibold text-sm md:text-base line-clamp-1 font-sora">{entry.title}</h3>
                        </Link>
                        {entry.episodeId && (
                            <p className="text-xs text-purple-400 font-bold mt-1">
                                {entry.type === 'tv' ? `Episode ${entry.episodeId}` : `Episode ${entry.episodeNumber || entry.episodeId}`}
                            </p>
                        )}
                        <p className="text-[10px] md:text-xs text-[var(--text-muted)] mt-1.5">{relativeTime(entry.updatedAt)}</p>
                      </div>

                      <div className="flex items-center gap-2 shrink-0">
                        <Link
                          href={getHistoryLink(entry)}
                          className="hidden sm:flex items-center gap-1.5 px-3 py-1.5 bg-white/5 hover:bg-white/10 border border-[var(--border-color)] rounded-lg text-xs font-bold transition-colors"
                        >
                          <Play className="w-3 h-3 fill-white" /> Resume
                        </Link>
                        <button
                          onClick={() => removeFromHistory(entry.id)}
                          className="p-1.5 md:p-2 text-[var(--text-muted)] hover:text-red-400 transition-colors rounded-lg hover:bg-red-500/10"
                        >
                          <Trash2 className="w-4 h-4 md:w-5 md:h-5" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </main>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import axios from "axios";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import { Calendar, CheckCircle, ChevronDown, ChevronUp, Clock, Film, Flame, Heart, History, Info, Laugh, LogOut, Play, Popcorn, Search, Skull, SlidersHorizontal, Sparkles, Star, Swords, TrendingUp, Tv, User, X, Zap } from "lucide-react";
import { MovieRow, MovieGrid, type MovieItem } from "@/components/MovieCard";
import HeroCarousel from "@/components/HeroCarousel";
import { AnimeGrid, AnimeCardHorizontal, type Show } from "@/components/AnimeCard";
import ContinueWatchingRow from "@/components/ContinueWatchingRow";
import useSWR from 'swr';

// CineVibe-style category sections with TMDB genre IDs
const GENRE_ROWS = [
    { title: "Action & Adventure", icon: Swords, genreId: "28", type: "movie" },
    { title: "Comedy", icon: Laugh, genreId: "35", type: "movie" },
    { title: "Romance", icon: Heart, genreId: "10749", type: "movie" },
    { title: "Horror & Thriller", icon: Skull, genreId: "27,53", type: "movie" },
    { title: "Animation", icon: Sparkles, genreId: "16", type: "movie" },
    { title: "Science Fiction", icon: Flame, genreId: "878", type: "movie" },
];

// Network IDs for streaming platform rows
const NETWORK_ROWS = [
    { title: "Netflix Originals", networkId: "213", logo: "🔴" },
    { title: "Prime Video", networkId: "1024", logo: "📦" },
    { title: "Disney+", networkId: "2739", logo: "🔵" },
    { title: "Hulu", networkId: "453", logo: "🟢" },
    { title: "HBO Shows", networkId: "49", logo: "🟣" },
    { title: "Apple TV+", networkId: "2552", logo: "⚪" },
    { title: "Paramount+", networkId: "4330", logo: "⛰️" },
    { title: "Peacock", networkId: "3353", logo: "🦚" },
];

// Nav tabs
const TABS = [
    { id: "movies", label: "Movies", icon: Popcorn },
    { id: "tv", label: "TV Shows", icon: Tv },
    { id: "anime", label: "Anime", icon: Sparkles },
    { id: "trending", label: "Trending", icon: TrendingUp },
];

export default function MoviesPage() {
    const [activeTab, setActiveTab] = useState("movies");
    const [trending, setTrending] = useState<MovieItem[]>([]);
    const [popular, setPopular] = useState<MovieItem[]>([]);
    const [topRated, setTopRated] = useState<MovieItem[]>([]);
    const [nowPlaying, setNowPlaying] = useState<MovieItem[]>([]);
    const [tvPopular, setTvPopular] = useState<MovieItem[]>([]);
    const [tvTopRated, setTvTopRated] = useState<MovieItem[]>([]);
    const [genreData, setGenreData] = useState<Record<string, MovieItem[]>>({});
    const [networkData, setNetworkData] = useState<Record<string, MovieItem[]>>({});
    const [animeLatest, setAnimeLatest] = useState<any[]>([]);
    const [animeTrending, setAnimeTrending] = useState<any[]>([]);
    const [searchQuery, setSearchQuery] = useState("");
    const [searchResults, setSearchResults] = useState<MovieItem[]>([]);
    const [isSearching, setIsSearching] = useState(false);
    const [trendingPeople, setTrendingPeople] = useState<any[]>([]);
    const [showScrollTop, setShowScrollTop] = useState(false);
    const [profile, setProfile] = useState<{name: string, avatar: string} | null>(null);

    // Fetch Movie Data for Unified Home
    const fetcher = (url: string) => axios.get(url).then(res => res.data);

    // Fetch current user from secure API
    const { data: userData } = useSWR('/api/auth/me', fetcher);

    useEffect(() => {
        if (userData?.user) {
            setProfile(userData.user);
        } else {
            setProfile(null);
        }
    }, [userData]);

    const { data: movieTrending } = useSWR('/api/prime/trending', fetcher);
    const { data: moviePopular } = useSWR('/api/prime?category=popular', fetcher);
    const { data: movieUpcoming } = useSWR('/api/prime?category=now_playing', fetcher);
    const { data: moviePeople } = useSWR('/api/prime/trending?type=person', fetcher);

    // Scroll-to-top visibility
    useEffect(() => {
        const handleScroll = () => setShowScrollTop(window.scrollY > 500);
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    useEffect(() => {
        if (movieTrending?.results) {
            const rawTrending = movieTrending.results || [];
            const validTrending = rawTrending.filter((item: MovieItem) => item && (item.poster_path || item.backdrop_path));
            const enhancedTrending = validTrending.map((item: MovieItem, index: number) => ({
                ...item,
                rank: index < 10 ? index + 1 : undefined,
                isMostViewed: index < 3,
                liveViewers: index < 10 ? Math.floor(Math.random() * (5000 - 1000) + 1000) : undefined
            }));
            setTrending(enhancedTrending);
        }
    }, [movieTrending]);

    useEffect(() => { if (moviePopular?.results) setPopular(moviePopular.results.filter((i: any) => i && (i.poster_path || i.backdrop_path))); }, [moviePopular]);
    useEffect(() => { if (movieUpcoming?.results) setNowPlaying(movieUpcoming.results.filter((i: any) => i && (i.poster_path || i.backdrop_path))); }, [movieUpcoming]);
    useEffect(() => { if (moviePeople?.results) setTrendingPeople(moviePeople.results.filter((i: any) => i && i.profile_path).slice(0, 6)); }, [moviePeople]);

    // Fetch main data sequentially (remaining axios calls)
    useEffect(() => {
        const loadOtherData = async () => {
            // Fetch top rated movies, tv popular, tv top rated
            try {
                const [topRatedRes, tvPopRes, tvTopRes] = await Promise.all([
                    axios.get("/api/prime?category=top_rated"),
                    axios.get("/api/prime/tv?category=popular"),
                    axios.get("/api/prime/tv?category=top_rated"),
                ]);

                setTopRated((topRatedRes.data.results || []).filter((i: any) => i && (i.poster_path || i.backdrop_path)));
                setTvPopular((tvPopRes.data.results || []).filter((i: any) => i && (i.poster_path || i.backdrop_path)));
                setTvTopRated((tvTopRes.data.results || []).filter((i: any) => i && (i.poster_path || i.backdrop_path)));
            } catch (err) {
                console.error("Failed to fetch main data:", err);
            }

            // Fetch genres (since we only show these for movies now, it fits the movies tab)
            try {
                const promises = GENRE_ROWS.map((genre) =>
                    axios.get(`/api/prime/discover?media_type=${genre.type}&genre_id=${genre.genreId}`)
                );
                const results = await Promise.allSettled(promises);
                const newGenreData: Record<string, MovieItem[]> = {};
                GENRE_ROWS.forEach((genre, i) => {
                    const res = results[i];
                    if (res.status === "fulfilled" && res.value.data.results?.length > 0) {
                        newGenreData[genre.title] = res.value.data.results.filter((i: any) => i && (i.poster_path || i.backdrop_path));
                    }
                });
                setGenreData(newGenreData);
            } catch (err) {
                console.error("Failed to fetch genres:", err);
            }

            // Fetch networks
            try {
                const promises = NETWORK_ROWS.map((net) =>
                    axios.get(`/api/prime/discover?media_type=tv&network_id=${net.networkId}`)
                );
                const results = await Promise.allSettled(promises);
                const newNetworkData: Record<string, MovieItem[]> = {};
                NETWORK_ROWS.forEach((net, i) => {
                    const res = results[i];
                    if (res.status === "fulfilled") {
                        if (res.value.data.results && res.value.data.results.length > 0) {
                            newNetworkData[net.title] = res.value.data.results;
                        }
                    }
                });
                setNetworkData(newNetworkData);
            } catch (err) {
                console.error("Failed to fetch network data:", err);
            }

            // Fetch Anime Home (Aniwaves)
            try {
                // Add random delay to mimic human behavior
                await new Promise(resolve => setTimeout(resolve, Math.random() * (2500 - 1200) + 1200));
                const animeRes = await axios.get("/api/anime/home");
                if (animeRes.data.latest) setAnimeLatest(animeRes.data.latest.filter((i: any) => i && i.image));
                if (animeRes.data.trending) setAnimeTrending(animeRes.data.trending.filter((i: any) => i && i.image));
            } catch (err) {
                console.error("Failed to fetch anime home:", err);
            }
        };

        loadOtherData();
    }, []);



    // Search handler
    useEffect(() => {
        if (!searchQuery.trim()) {
            setSearchResults([]);
            setIsSearching(false);
            return;
        }
        setIsSearching(true);
        const timer = setTimeout(async () => {
            try {
                const res = await axios.get(`/api/search/unified?q=${encodeURIComponent(searchQuery)}`);
                setSearchResults(res.data.results || []);
            } catch (err) {
                console.error("Search failed:", err);
            } finally {
                setIsSearching(false);
            }
        }, 400);
        return () => clearTimeout(timer);
    }, [searchQuery]);

    // Check for search query in URL
    const paramsInUrl = useSearchParams();
    useEffect(() => {
        const q = paramsInUrl?.get('q');
        if (q) {
            setSearchQuery(q);
        }
    }, [paramsInUrl]);

    return (
        <div className="bg-[var(--bg-main)] text-[var(--text-main)] selection:bg-purple-500/30 transition-colors duration-300">
            {/* Background Ambience */}
            <div className="fixed inset-0 z-0 pointer-events-none">
                <div className="absolute top-0 left-0 w-full h-[500px] bg-gradient-to-b from-blue-900/10 to-transparent opacity-50" />
            </div>

            <div className="relative z-10 w-full pb-24 md:pb-0">
                <h1 className="sr-only">ToonPlayer - Watch Free Anime & Movies</h1>
                <HeroCarousel />

                {/* Genres & Categories Sub-Nav */}
                <div className="bg-[var(--bg-card)]/80 backdrop-blur-md border-y border-[var(--border-color)] sticky top-16 md:top-[72px] z-40">
                    <div className="w-full mx-auto px-4 md:px-6 py-2 flex items-center justify-between">
                        <div className="flex items-center gap-1 overflow-x-auto hide-scrollbar z-50">
                            {TABS.map((tab) => (
                                <button
                                    key={tab.id}
                                    onClick={() => setActiveTab(tab.id)}
                                    className={`flex items-center gap-2 px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all cursor-pointer relative z-50 ${activeTab === tab.id
                                        ? "bg-blue-500 text-white shadow-lg shadow-blue-500/20"
                                        : "text-[var(--text-muted)] hover:text-white hover:bg-white/5"
                                    }`}
                                >
                                    <tab.icon className="w-3.5 h-3.5" />
                                    {tab.label}
                                </button>
                            ))}
                        </div>
                        <div className="hidden lg:flex items-center gap-2 pl-4 border-l border-[var(--border-color)] ml-4">
                            <span className="text-[10px] uppercase tracking-wider font-black text-[var(--text-muted)]">Quick Filters:</span>
                            {GENRE_ROWS.slice(0, 4).map(g => (
                                <button 
                                    key={g.genreId}
                                    onClick={() => document.getElementById(`genre-${g.genreId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' })}
                                    className="px-2.5 py-1 text-[10px] font-bold text-[var(--text-muted)] hover:text-white transition-colors"
                                >
                                    {g.title}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="w-full px-4 md:px-8 py-4 md:py-8">
                    {searchQuery ? (
                        <div className="space-y-8">
                            <h2 className="text-2xl font-black text-white flex items-center gap-3">
                                <Search className="w-6 h-6 text-purple-400" />
                                {isSearching ? "Searching..." : `Results for "${searchQuery}"`}
                            </h2>
                            {searchResults.length > 0 ? (
                                <div className="responsive-grid">
                                    {searchResults.map((item: any) => (
                                        <Link
                                            key={`${item.type}-${item.id}`}
                                            href={item.href}
                                            className="group relative bg-[var(--bg-card)] rounded-xl overflow-hidden border border-[var(--border-color)] hover:border-purple-500/50 transition-all hover:scale-[1.02] duration-300 shadow-lg"
                                        >
                                            <div className="aspect-[2/3] relative">
                                                <img src={item.image} alt={item.title} className="w-full h-full object-cover" />
                                                <div className="absolute top-2 right-2 px-2 py-1 rounded bg-black/80 backdrop-blur-md text-[10px] font-black uppercase tracking-tighter text-white border border-white/10">
                                                    {item.type}
                                                </div>
                                            </div>
                                            <div className="p-3">
                                                <h3 className="text-sm font-bold text-white truncate leading-tight mb-1 group-hover:text-purple-400 transition-colors tracking-tight">{item.title}</h3>
                                                <div className="flex items-center justify-between text-[10px] text-[var(--text-muted)] font-medium">
                                                    <span>{item.format}</span>
                                                    <span>{item.year}</span>
                                                </div>
                                            </div>
                                        </Link>
                                    ))}
                                </div>
                            ) : (
                                !isSearching && <div className="text-center py-20 text-[var(--text-muted)]">No results found for your search.</div>
                            )}
                        </div>
                    ) : (
                        <div className="flex flex-col lg:flex-row gap-6 md:gap-10">
                            {/* Main Feed */}
                            <div className="flex-1 min-w-0">
                                <ContinueWatchingRow />

                                {activeTab === "movies" && (
                                    <div className="space-y-12">
                                        <section>
                                            <SectionHeader icon={Flame} title="Trending Movies" color="text-red-400" />
                                            {trending.filter(m => (m as any).media_type === 'movie' || !m.name).length > 0 ? <MovieRow items={trending.filter(m => (m as any).media_type === 'movie' || !m.name)} title="movie-trending" /> : <RowSkeleton />}
                                        </section>
                                        <section>
                                            <SectionHeader icon={Film} title="Popular Movies" color="text-blue-400" />
                                            {popular.length > 0 ? <MovieRow items={popular} type="movie" title="movies-popular" /> : <RowSkeleton />}
                                        </section>
                                        <section>
                                            <SectionHeader icon={Popcorn} title="Now Playing in Theaters" color="text-yellow-400" />
                                            {nowPlaying.length > 0 ? <MovieRow items={nowPlaying} type="movie" title="now-playing" /> : <RowSkeleton />}
                                        </section>
                                        <section>
                                            <SectionHeader icon={Star} title="Top Rated Movies" color="text-yellow-400" />
